'use strict';

function decodeHtml(value) {
  const named = {
    amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ',
    middot: '·', ndash: '–', mdash: '—'
  };
  return String(value || '')
    .replace(/&#(x[0-9a-f]+|[0-9]+);?/gi, function (_, code) {
      const number = code.charAt(0).toLowerCase() === 'x' ?
        parseInt(code.slice(1), 16) : parseInt(code, 10);
      if (!Number.isFinite(number) || number < 0 || number > 0x10ffff) return '';
      try { return String.fromCodePoint(number); } catch (_) { return ''; }
    })
    .replace(/&([a-z]+);/gi, function (match, name) {
      return Object.prototype.hasOwnProperty.call(named, name.toLowerCase()) ?
        named[name.toLowerCase()] : match;
    });
}

function plainText(value) {
  return decodeHtml(String(value || '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/?[a-z][a-z0-9]*(?:\s[^>]*)?>/gi, ' '))
    .replace(/[\t\r\n ]+/g, ' ')
    .replace(/([“‘（【《〈])\s+/g, '$1')
    .replace(/\s+([”’）】》〉，。！？；：、])/g, '$1')
    .trim();
}

function normalizeTerm(value) {
  const selected = String(value || '').trim()
    .replace(/^[\s"'“”‘’《》〈〉【】\[\]（）()，。！？、；：]+/, '')
    .replace(/[\s"'“”‘’《》〈〉【】\[\]（）()，。！？、；：]+$/, '');
  return selected.slice(0, 64);
}

function collectMatches(html, className, limit) {
  const values = [];
  const pattern = new RegExp("<([a-z0-9]+)[^>]+class=[\"'][^\"']*" + className +
    "[^\"']*[\"'][^>]*>([\\s\\S]*?)<\\/\\1>", 'gi');
  let match;
  while ((match = pattern.exec(html)) && values.length < limit) {
    const text = plainText(match[2]).slice(0, 12000);
    if (text && values.indexOf(text) < 0) values.push(text);
  }
  return values;
}

function structuredFallback(html) {
  const match = html.match(/<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/i);
  if (!match) return { name: '', description: '' };
  try {
    const data = JSON.parse(match[1]);
    return {
      name: plainText(data && data.name),
      description: plainText(data && data.description)
    };
  } catch (_) {
    return { name: '', description: '' };
  }
}

module.exports.dictionary = async function (input) {
  const value = input || {};
  const term = normalizeTerm(value.word || value.context);
  if (!term) return { title: '汉典中文辞典', text: '请选择要查询的汉字或中文词语。' };
  if (term.length > 32) {
    return { title: term + ' · 汉典中文辞典', text: '选择内容过长，请缩小到一个汉字或词语后再查询。' };
  }

  try {
    const response = await Promise.resolve(reader.http.fetch({
      url: 'https://zdic.net/hans/' + encodeURIComponent(term),
      method: 'GET',
      headers: {
        'Accept': 'text/html,application/xhtml+xml',
        'Accept-Language': 'zh-CN,zh;q=0.9',
        'User-Agent': 'Mozilla/5.0 FishReaderDictionary/1.0'
      },
      timeoutMs: 15000
    }));
    const status = Number(response && response.status || 0);
    const html = String(response && response.body || '');
    if (status === 404) {
      return { title: term + ' · 汉典中文辞典', text: '暂未收录该词条。' };
    }
    if (status < 200 || status >= 400 || !html) {
      return { title: term + ' · 汉典中文辞典', text: '查询失败：HTTP ' + status + '。' };
    }

    const pinyin = collectMatches(html, '(?:xxjs|jbjs)-reading__py', 4);
    let definitions = collectMatches(html, '(?:xxjs|jbjs)-item__def', 12);
    const nationalDefinitions = collectMatches(html, 'gy-sense__def', 4);
    nationalDefinitions.forEach(function (item) {
      if (definitions.indexOf(item) < 0 && definitions.length < 12) definitions.push(item);
    });
    const fallback = structuredFallback(html);
    if (definitions.length === 0 && fallback.description) definitions = [fallback.description];
    if (definitions.length === 0) {
      return { title: term + ' · 汉典中文辞典', text: '暂未找到可显示的释义。' };
    }

    const lines = [];
    if (pinyin.length > 0) lines.push('拼音：' + pinyin.join('；'));
    if (lines.length > 0) lines.push('');
    definitions.forEach(function (definition, index) {
      lines.push(String(index + 1) + '. ' + definition);
    });
    lines.push('', '数据：汉典（在线查询）');
    return { title: (fallback.name || term) + ' · 汉典中文辞典', text: lines.join('\n') };
  } catch (error) {
    const message = (error && error.message ? String(error.message) :
      String(error || '未知错误')).slice(0, 500);
    return { title: term + ' · 汉典中文辞典', text: '查询失败：' + message };
  }
};
